-- An `ON UPDATE CASCADE` fires once the statement's rows are written, so a later target
-- row's CHECK outranks the oversized child entry the earlier row's cascade would write.
-- @setup
CREATE TABLE p (k text PRIMARY KEY, v int CHECK (v > 0));
CREATE TABLE c (pad text, k text REFERENCES p ON UPDATE CASCADE);
CREATE INDEX c_i ON c (pad, k);
INSERT INTO p VALUES ('a', 1), ('b', 1);
INSERT INTO c VALUES ('', 'a');
-- @test
-- @expect-error: the second row fails its CHECK before the cascade runs
-- @expect-message
-- @profile-lock
UPDATE p SET k = CASE WHEN k = 'a' THEN '' ELSE k END, v = CASE WHEN k = 'b' THEN -1 ELSE v END;
